import React, { useEffect, useState, useCallback } from "react";

import { v4 as uuidv4 } from 'uuid';

import { Question, Message, DomainStatus, AnswerAttempt } from './types'; // Ensure AnswerAttempt is imported

import Header from './components/Header';

import ChatPanel from './components/ChatPanel';

import Sidebar from './components/Sidebar';



const App: React.FC = () => {

  const [questions, setQuestions] = useState<Question[]>([]);

  const [currentQuestionId, setCurrentQuestionId] = useState<number | null>(null);

  const [messages, setMessages] = useState<Message[]>([]);

  const [domainStatuses, setDomainStatuses] = useState<DomainStatus[]>([]);

  const [overallScore, setOverallScore] = useState<number>(0);

  const [isLoading, setIsLoading] = useState<boolean>(true);

  const [editingMessageId, setEditingMessageId] = useState<string | null>(null);



  // Initial data fetching (no changes needed here)

  useEffect(() => {

    fetch("http://localhost:3001/questions").then(res => {

        if (!res.ok) throw new Error(`Network response was not ok: ${res.statusText}`);

        return res.json();

    }).then(data => {

      if (!Array.isArray(data) || data.length === 0) throw new Error("Fetched data is not valid.");

      setQuestions(data);

      const firstQuestion = data[0];

      setCurrentQuestionId(firstQuestion.id);

      setMessages([{

        id: uuidv4(), sender: 'AI', type: 'question', question: firstQuestion,

        text: ""

      }]);

      const initialDomains: DomainStatus[] = [...new Set(data.map(q => q.domain_name))].map(name => ({ name, status: name === firstQuestion.domain_name ? 'In Progress' : 'Pending', score: 0 }));

      setDomainStatuses(initialDomains);

    }).catch(err => {

      console.error("Error fetching questions:", err);

      setMessages([{ id: uuidv4(), sender: 'AI', type: 'error', text: "Backend'e bağlanılamadı." }]);

    }).finally(() => setIsLoading(false));

  }, []);



  // UPDATED: This function now correctly reads scores from the active attempt within each user_response message.

  const recalculateScores = useCallback((currentMessages: Message[], allQuestions: Question[]) => {

    if (allQuestions.length === 0) return;



    const domainData: { [key: string]: { score: number; answeredQuestions: Set<number> } } = {};

    const domains = [...new Set(allQuestions.map(q => q.domain_name))];



    domains.forEach(name => {

        domainData[name] = { score: 0, answeredQuestions: new Set() };

    });



    for (const msg of currentMessages) {

        if (msg.type === 'user_response' && msg.answeredQuestionId && msg.attempts && msg.activeAttemptIndex !== undefined) {

            const question = allQuestions.find(q => q.id === msg.answeredQuestionId);

            if (question) {

                // To prevent double-counting scores if a user navigates back and forth,

                // we mark the question as "scored" for this calculation run.

                domainData[question.domain_name].answeredQuestions.add(question.id);

            }

        }

    }



    domains.forEach(name => {

        const totalQuestionsInDomain = allQuestions.filter(q => q.domain_name === name).length;

        const questionWeight = 100 / (totalQuestionsInDomain || 1);

        let domainScore = 0;



        // Find the user responses relevant to this domain

        currentMessages.filter(m => m.type === 'user_response' && m.answeredQuestionId && domainData[name].answeredQuestions.has(m.answeredQuestionId))

            .forEach(msg => {

                const activeAttempt = msg.attempts?.[msg.activeAttemptIndex || 0];

                if (activeAttempt) {

                    domainScore += (activeAttempt.score / 100) * questionWeight;

                }

            });

        domainData[name].score = domainScore;

    });



    const lastQuestionMsg = [...currentMessages].reverse().find(m => m.type === 'question' && m.question);

    const currentDomainName = lastQuestionMsg?.question?.domain_name;



    const newDomainStatuses: DomainStatus[] = domains.map(name => {

        const data = domainData[name];

        const answeredCount = data.answeredQuestions.size;

        const totalCount = allQuestions.filter(q => q.domain_name === name).length;

        let status: 'Complete' | 'In Progress' | 'Pending' = 'Pending';



        if (answeredCount > 0) {

            status = (answeredCount >= totalCount || name !== currentDomainName) ? 'Complete' : 'In Progress';

        } else if (name === currentDomainName) {

            status = 'In Progress';

        }



        return { name, score: Math.min(100, data.score), status };

    });



    const totalScore = newDomainStatuses.reduce((acc, curr) => acc + curr.score, 0);

    setOverallScore(totalScore / (newDomainStatuses.length || 1));

    setDomainStatuses(newDomainStatuses);

  }, []);



  const getVisibleMessages = (allMessages: Message[]): Message[] => {

    if (allMessages.length === 0) {

      return [];

    }



    const visible: Message[] = [];

    // The first message (the first question) is always visible.

    visible.push(allMessages[0]);



    for (let i = 0; i < allMessages.length - 1; i++) {

      const currentMessage = allMessages[i];

      const nextMessage = allMessages[i + 1];



      if (currentMessage.type === 'question') {

        // If the next message is a response to this question, it's visible.

        if (nextMessage.type === 'user_response' && nextMessage.answeredQuestionId === currentMessage.question?.id) {

          visible.push(nextMessage);

        } else {

          // The path ends here.

          break;

        }

      } else if (currentMessage.type === 'user_response') {

        // Find the active attempt to determine the correct next question.

        const activeAttempt = currentMessage.attempts?.[currentMessage.activeAttemptIndex || 0];

        if (!activeAttempt) break; // Path ends if no active attempt



        // If the next message in the source array is the correct next question, it's visible.

        if (nextMessage.type === 'question' && nextMessage.question?.id === activeAttempt.next_question_id) {

          visible.push(nextMessage);

        } else {

          // The path ends here.

          break;

        }

      }

    }

   

    return visible;

  };

 

  const createNextQuestionMessage = (nextId: number | null): Message | null => {

    if (nextId === null) {

      return { id: uuidv4(), sender: 'AI', type: 'question', text: '🎉 Assessment complete!' };

    }

    const nextQuestion = questions.find(q => q.id === nextId);

    return nextQuestion ? {

      id: uuidv4(), sender: 'AI', type: 'question', question: nextQuestion,

      text: ""

    } : null;

  };



  const visibleMessages = getVisibleMessages(messages);



  const handleSendMessage = async (prompt: string) => {

    if (!currentQuestionId || isLoading) return;

    setIsLoading(true);



    const optimisticUserMessage: Message = {

      id: uuidv4(),

      sender: 'User',

      type: 'user_response',

      answeredQuestionId: currentQuestionId,

      attempts: [{ text: prompt, score: 0, ai_comment: "...", ai_task: "...", db_answer_id: -1, next_question_id: null }],

      activeAttemptIndex: 0,

      text: ""

    };

    setMessages(prev => [...prev, optimisticUserMessage]);



    try {

      const res = await fetch("http://localhost:3001/ask", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ prompt, previous_question_id: currentQuestionId }) });

      if (!res.ok) throw new Error(`API error: ${res.statusText}`);

      const apiResponse = await res.json();



      const newAttempt: AnswerAttempt = {

        text: prompt,

        score: apiResponse.score,

        ai_comment: apiResponse.comment,

        ai_task: apiResponse.task,

        db_answer_id: apiResponse.db_answer_id,

        next_question_id: apiResponse.next_question_id,

      };



      const finalMessages = [...messages];

      const userMessage: Message = {

        id: uuidv4(),

        sender: 'User',

        type: 'user_response',

        answeredQuestionId: currentQuestionId,

        attempts: [newAttempt],

        activeAttemptIndex: 0,

        text: ""

      };

      finalMessages.push(userMessage);



      const nextQuestionMessage = createNextQuestionMessage(apiResponse.next_question_id);

      if (nextQuestionMessage) {

        finalMessages.push(nextQuestionMessage);

      }

     

      setMessages(finalMessages);

      setCurrentQuestionId(apiResponse.next_question_id);

      recalculateScores(finalMessages, questions);



    } catch (err) {

      console.error("Error sending message:", err);

      setMessages(messages); // Revert optimistic update on error

    } finally {

      setIsLoading(false);

    }

  };



  const handleEditMessage = async (messageId: string, newText: string) => {

  const messageIndex = messages.findIndex(m => m.id === messageId);

  if (messageIndex === -1) return;



  const originalMessage = messages[messageIndex];

  if (!originalMessage.answeredQuestionId || !originalMessage.attempts) return;



  setIsLoading(true);

  setEditingMessageId(null);



  try {

    const dbAnswerIdToUpdate = originalMessage.attempts[originalMessage.activeAttemptIndex || 0]?.db_answer_id;



    const res = await fetch("http://localhost:3001/ask", {

      method: "POST", headers: { "Content-Type": "application/json" },

      body: JSON.stringify({ prompt: newText, previous_question_id: originalMessage.answeredQuestionId, answer_id_to_edit: dbAnswerIdToUpdate }),

    });

    if (!res.ok) throw new Error(`API error: ${res.statusText}`);

    const apiResponse = await res.json();



    const newAttempt: AnswerAttempt = {

      text: newText,

      score: apiResponse.score,

      ai_comment: apiResponse.comment,

      ai_task: apiResponse.task,

      db_answer_id: apiResponse.db_answer_id,

      next_question_id: apiResponse.next_question_id,

    };



    setMessages(currentMessages => {

        const updatedMessages = [...currentMessages];

        const messageToUpdate = updatedMessages[messageIndex];

        messageToUpdate.attempts?.push(newAttempt);

        messageToUpdate.activeAttemptIndex = (messageToUpdate.attempts?.length || 1) - 1;



        // Check if there's already a question after this answer.

        if (messageIndex + 1 < updatedMessages.length) {

            // If the next message isn't the one we need, we would handle that here.

            // For now, we assume a new edit creates a new branch end.

        }

       

        return updatedMessages;

    });



  } catch (err) {

      console.error("Error while editing message:", err);

  } finally {

      setIsLoading(false);

  }

  };



  const handleNavigateAttempt = (messageId: string, direction: 'prev' | 'next') => {

    const msgIndex = messages.findIndex(m => m.id === messageId);

    if (msgIndex === -1) return;



    // We update the state directly without rebuilding the array here.

    // The change will be reflected by the new getVisibleMessages function.

    setMessages(currentMessages => {

        const updatedMessages = [...currentMessages];

        const msg = updatedMessages[msgIndex];

        if (!msg.attempts || msg.activeAttemptIndex === undefined) return currentMessages;



        const newIndex = msg.activeAttemptIndex + (direction === 'next' ? 1 : -1);

        if (newIndex < 0 || newIndex >= msg.attempts.length) return currentMessages;



        msg.activeAttemptIndex = newIndex;

        return updatedMessages;

    });

  };



 

 

  const handlePreviousQuestion = () => {

    let lastUserResponseIndex = -1;

    for (let i = messages.length - 1; i >= 0; i--) {

        if (messages[i].type === 'user_response') {

            lastUserResponseIndex = i;

            break;

        }

    }

    if (lastUserResponseIndex === -1) return;



    const newMessages = messages.slice(0, lastUserResponseIndex);

    const lastQuestionInNewHistory = [...newMessages].reverse().find(m => m.type === 'question');

   

    setMessages(newMessages);

    setCurrentQuestionId(lastQuestionInNewHistory?.question?.id || null);

    recalculateScores(newMessages, questions);

  };



  return (

    <div className="bg-[#0f0f23] text-gray-200 font-sans h-screen flex flex-col">

      <Header onPrevious={handlePreviousQuestion} canGoBack={messages.some(m => m.type === 'user_response')} />

      <div className="flex flex-1 overflow-hidden min-h-0">

        <ChatPanel

          messages={messages}

          onSendMessage={handleSendMessage}

          isLoading={isLoading}

          currentQuestionId={currentQuestionId}

          editingMessageId={editingMessageId}

          setEditingMessageId={setEditingMessageId}

          onEditMessage={handleEditMessage}

          onNavigateAttempt={handleNavigateAttempt}

        />

        <Sidebar statuses={domainStatuses} overallScore={overallScore} />

      </div>

    </div>

  );

};



export default App;
